type ProjectBoundary='start'|'end';
type Activity={id:string;name:string;status:string;priority:string;start_date:string;due_date:string;notes:string;project_id:string;activity_type_id?:string;project_timing_rule?:ProjectTimingRule|null;project_timing_boundary?:ProjectBoundary|null;project_timing_offset_days?:number|null;archived_at?:string|null;projects?:{id:string;name:string;start_date:string;end_date:string};activity_types?:TypeRow;activity_owners?:{team_members:Member}[];activity_links?:ActivityLink[];activity_dependencies?:Dependency[]};
