const isoDate=(value:Date)=>{const local=new Date(value.getTime()-value.getTimezoneOffset()*60000);return local.toISOString().slice(0,10)};
const addDays=(value:string,days:number)=>{const next=new Date(`${value}T12:00:00`);next.setDate(next.getDate()+days);return isoDate(next)};
const dayDifference=(earlier:string,later:string)=>Math.round((new Date(`${later}T12:00:00`).getTime()-new Date(`${earlier}T12:00:00`).getTime())/86400000);
const boundaryLabel=(boundary:ProjectBoundary)=>boundary==='start'?'project start date':'project end date';
function projectTimingDeadline(project:Project,rule:ProjectTimingRule,boundary:ProjectBoundary,offset:number){return rule==='advance_deadline'?addDays(boundary==='start'?project.start_date:project.end_date,-offset):addDays(project.end_date,offset)}
