function OwnerPicker({members,selected,onChange,label,copy}:{members:Member[];selected:string[];onChange:(ids:string[])=>void;label:string;copy:string}){return <fieldset className="form-section owner-picker"><legend>{label}</legend><p>{copy}</p><div>{members.map(member=><label key={member.id}><input type="checkbox" checked={selected.includes(member.id)} onChange={()=>onChange(selected.includes(member.id)?selected.filter(id=>id!==member.id):[...selected,member.id])}/><span className="avatar">{member.initials}</span><strong>{member.full_name}</strong></label>)}</div></fieldset>}
function LinkEditor({links,onChange}:{links:ActivityLink[];onChange:(links:ActivityLink[])=>void}){return <fieldset className="form-section link-editor"><legend>External links</legend><p>Add reference documents, menus, vendor pages, or other URLs needed for the work.</p>{links.map((link,index)=><div className="link-edit-row" key={link.id||index}><input aria-label={`Link ${index+1} label`} placeholder="Label (optional)" value={link.label||''} onChange={e=>onChange(links.map((item,i)=>i===index?{...item,label:e.target.value}:item))}/><input aria-label={`Link ${index+1} URL`} type="url" placeholder="https://" value={link.url} onChange={e=>onChange(links.map((item,i)=>i===index?{...item,url:e.target.value}:item))}/><button type="button" onClick={()=>onChange(links.filter((_,i)=>i!==index))}>Remove</button></div>)}<button type="button" className="secondary-btn add-link" onClick={()=>onChange([...links,{label:'',url:''}])}>＋ Add link</button></fieldset>}
function FormActions({busy,onCancel}:{busy:boolean;onCancel:()=>void}){return <div className="form-actions"><button type="button" className="secondary-btn" onClick={onCancel}>Cancel</button><button className="create-btn" disabled={busy}>{busy?'Saving…':'Save'}</button></div>}
